import React from "react";
import { Button, Checkbox, Form, FormInstance, FormListFieldData, Input, Tabs, Spin } from "antd";

import { AppContext } from "../../context";
import { DashboardLink, DBForm, EMPTY_APPLICATION, EMPTY_LINK } from "../../types";
import { AppIcon } from "../SVGFiles";
import { MenuFormFields } from "./forms/MenuFormFields";
import { PlusOutlined } from "@ant-design/icons";
import { WidgetsForm } from "./forms/Widgets";
import { ConfigHeading } from "../ConfigHeading";

export const AppDashboard = () => {
    const { state, saveDashboardConfig } = React.useContext(AppContext);
    const [formValues, setFormValues] = React.useState<DBForm>();
    const [activeTab, setActiveTab] = React.useState("0");
    const [lastActiveTab, setLastActiveTab] = React.useState("0");
    const [formDisabled, setFormDisabled] = React.useState(false);
    const [form] = Form.useForm<DBForm>();

    React.useEffect(() => {
        setFormValues({
            Apps: state.dashboardLinks,
            Id: state.dashboardProps.Id,
            Url: state.dashboardProps.Url,
            Enabled: false,
        });
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const onFinish = async (values: DBForm) => {
        setFormDisabled(true);
        values.Apps.forEach((app, i) => {
            app.Widgets = app.Widgets && app.Widgets.length ? app.Widgets : [];
            app.Rank = i + 1;
            if (app.isNew) {
                app.Name = app.Link.Text.replaceAll(" ", "");
                app.Link.Name = app.Link.Text.replaceAll(" ", "");

                app.Link.Menu.forEach((menu) => {
                    menu.Name = menu.Text.replaceAll(" ", "");
                });
            }
        });
        await saveDashboardConfig({ ...values, Forms: state.formLinks || [] });
        setFormDisabled(false);
    };

    if (!formValues) {
        return null;
    }

    return (
        <Spin spinning={formDisabled} tip="Saving configuration...">
            <Form
                name="ss-links"
                onFinish={onFinish}
                initialValues={formValues}
                autoComplete={"off"}
                layout="horizontal"
                form={form}
                disabled={formDisabled}>
                <ConfigHeading title="Dashboard Configuration" />
                <div className="ss-app-config-box shadow ss-app-config-dashboard">
                    <div>
                        <Form.Item name="Id" noStyle>
                            <Input type="hidden" />
                        </Form.Item>
                        <Form.Item
                            label="Host URL"
                            name="Url"
                            rules={[
                                {
                                    required: true,
                                    message: "Please input your host URL.",
                                },
                                {
                                    type: "url",
                                    message: "Invalid Link address.",
                                },
                            ]}>
                            <Input />
                        </Form.Item>
                        <Form.Item name="Enabled" label="Enabled" valuePropName="checked">
                            <Checkbox />
                        </Form.Item>
                    </div>
                    <div className="ss-app-config-form-list">
                        <Form.List name={["Apps"]}>
                            {(fields, { add }) => {
                                return (
                                    <ApplicationFormList
                                        form={form}
                                        fields={fields}
                                        addApp={add}
                                        activeTab={activeTab}
                                        onAddApplication={() => {
                                            setLastActiveTab(activeTab);
                                            setActiveTab((form.getFieldsValue().Apps.length - 1).toString());
                                        }}
                                        onTabChange={(key, isRemoveEvent) => {
                                            if (isRemoveEvent) {
                                                setActiveTab(lastActiveTab);
                                            } else {
                                                setActiveTab(() => {
                                                    setLastActiveTab(activeTab);
                                                    return key;
                                                });
                                            }
                                        }}
                                    />
                                );
                            }}
                        </Form.List>
                    </div>
                </div>
            </Form>
        </Spin>
    );
};

export const LinkTabLabel: React.FC<{
    Icon: string;
    Name: string;
    Text: string;
}> = ({ Name, Icon, Text }) => (
    <div className="ss-app-config-nav-item">
        <AppIcon className="link-icon" asset={Icon} />
        <span className="ss-app-config-nav-item-label">{Text || Name}</span>
    </div>
);

const ApplicationFormList: React.FC<{
    fields: FormListFieldData[];
    addApp?: (defaultValue?: any, insertIndex?: number | undefined) => void;
    form: FormInstance<DBForm>;
    activeTab: string;
    onAddApplication: () => void;
    onTabChange: (key: string, remove?: boolean) => void;
}> = ({ fields, addApp, form, activeTab, onAddApplication, onTabChange }) => {
    const Apps: DashboardLink[] = Form.useWatch(["Apps"], form);
    if (!Apps) return null;
    return (
        <>
            <h3>
                <span>Applications</span>
                <span>
                    <Button
                        type="primary"
                        icon={<PlusOutlined />}
                        onClick={() => {
                            addApp && addApp(EMPTY_APPLICATION);
                            onAddApplication();
                        }}>
                        <span className="m-l-8">New Application</span>
                    </Button>
                </span>
            </h3>
            <Tabs activeKey={activeTab} tabPosition="left" onTabClick={(key) => onTabChange(key)}>
                {fields.map(({ name }, _AppIndex) => {
                    const App = Apps[_AppIndex];
                    return (
                        <Tabs.TabPane
                            key={_AppIndex}
                            tab={<LinkTabLabel Name={App.Name} Icon={App.Link.Icon} Text={App.Link.Text} />}>
                            <div className="ss-app-config-group-links">
                                <h4>Link</h4>
                                <div className="ss-app-config-group-toolbar">
                                    {App.ShowName && (
                                        <Button
                                            danger
                                            size="small"
                                            icon={
                                                <AppIcon
                                                    className="m-r-4"
                                                    asset="delete"
                                                    width="16"
                                                    height="16"
                                                    stroke="#ff4d4f"
                                                />
                                            }
                                            onClick={() => {
                                                let vals = form.getFieldsValue();
                                                vals.Apps = vals.Apps.filter((_: any, i: number) => i !== _AppIndex);
                                                form.setFieldsValue(vals);
                                                onTabChange((vals.Apps.length - 1).toString(), true);
                                            }}>
                                            {App.isNew ? "Cancel" : "Remove application"}
                                        </Button>
                                    )}
                                </div>
                            </div>
                            <MenuFormFields name={[name, "Link"]} showLink={true} hideNameField={true} />
                            {App?.Widgets?.length ? (
                                <Form.List name={[name, "Widgets"]}>
                                    {(fields) => (
                                        <>
                                            <div className="ss-app-config-group-links">
                                                <h4>Widgets</h4>
                                            </div>
                                            {fields.map(({ key, name }, _widgetIndex) => (
                                                <WidgetsForm
                                                    name={[name]}
                                                    key={key}
                                                    widget={Apps[_AppIndex].Widgets[_widgetIndex]}
                                                />
                                            ))}
                                        </>
                                    )}
                                </Form.List>
                            ) : null}
                            <Form.List name={[name, "Link", "Menu"]}>
                                {(fields, { add }) => (
                                    <>
                                        <div className="ss-app-config-group-links">
                                            <h4>Menu</h4>
                                            <div className="ss-app-config-group-toolbar">
                                                <Button
                                                    size="small"
                                                    icon={
                                                        <AppIcon asset="plus" height="16" width="16" stroke="#1268b3" />
                                                    }
                                                    onClick={() => {
                                                        add(EMPTY_LINK);
                                                    }}>
                                                    Add menu
                                                </Button>
                                            </div>
                                        </div>
                                        <div className="ss-app-config-nav-links">
                                            {fields.map(({ key, name }, _linkIndex) => {
                                                const navLink = App.Link.Menu[_linkIndex];
                                                return (
                                                    <div key={key} className="ss-app-config-dbnav-item">
                                                        {navLink?.Show && (
                                                            <MenuDeleteButton
                                                                appIndex={_AppIndex}
                                                                linkIndex={_linkIndex}
                                                                Apps={Apps}
                                                                form={form}
                                                            />
                                                        )}
                                                        <MenuFormFields
                                                            name={[name]}
                                                            showLink={navLink?.Show || false}
                                                            hideNameField={true}
                                                        />
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </>
                                )}
                            </Form.List>
                        </Tabs.TabPane>
                    );
                })}
            </Tabs>
        </>
    );
};

export const MenuDeleteButton: React.FC<{
    Apps: DashboardLink[];
    form: FormInstance<DBForm>;
    appIndex: number;
    linkIndex: number;
}> = ({ Apps, form, appIndex, linkIndex }) => (
    <Button
        danger
        icon={<AppIcon asset="delete" width="20" height="20" stroke="#ffffff" />}
        type="primary"
        shape="circle"
        className="ss-app-config-dbnav-item-delete"
        onClick={() => {
            const menus = Apps[appIndex].Link.Menu.filter((_, i) => i !== linkIndex);
            const values = form.getFieldsValue();
            values.Apps.forEach((app: any, _appInx: number) => {
                if (_appInx === appIndex) {
                    app.Link.Menu = menus;
                }
            });
            form.setFieldsValue(values);
        }}
    />
);
