import React from "react";
import { Button, Form, Input, Tabs, Spin } from "antd";

import { CleverForms, EMPTY_FORM } from "../../types";
import { AppIcon } from "../SVGFiles";
import { getCleverFormsConfig, saveCleverFormsConfig } from "../../remote";
import { PlusOutlined } from "@ant-design/icons";

import { LinkTabLabel } from "./AppDashboard";
import { MenuFormFields } from "./forms/MenuFormFields";
import { ConfigHeading } from "../ConfigHeading";

export const AppCleverForms = () => {
    const [formValues, setFormValues] = React.useState<CleverForms>();
    const [formDisabled, setFormDisabled] = React.useState(false);
    const [form] = Form.useForm<CleverForms>();
    const [activeTab, setActiveTab] = React.useState("0");

    React.useEffect(() => {
        getCleverFormsConfig().then((res) => {
            if (res.status === 200) {
                setFormValues(res.data);
                form.setFieldsValue(res.data);
            }
        });

        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const onFinish = async (values: CleverForms) => {
        setFormDisabled(true);
        if (formValues) {
            const newValues = {
                ...formValues,
                ...values,
            };
            await saveCleverFormsConfig(newValues);
            setFormValues(newValues);
        }
        setFormDisabled(false);
    };

    return (
        <Spin
            spinning={formValues === undefined || formDisabled}
            tip={formDisabled ? "Saving configuration" : "Loading My Pay configuration"}>
            <Form
                name="ss-links"
                onFinish={onFinish}
                autoComplete={"off"}
                layout="horizontal"
                form={form}
                disabled={formDisabled}
                onValuesChange={(changeCFval, cf) => {
                    cf.Forms.forEach((form, i) => {
                        if (changeCFval.Forms[i]) {
                            const { Text } = changeCFval.Forms[i];
                            if (form.IsNew && Text) {
                                form.Name = form.Text.replaceAll(" ", "");
                            }
                        }
                    });
                    form.setFieldsValue(cf);
                }}>
                <ConfigHeading title="Clever Forms Configuration" />
                <div className="ss-app-config-box shadow ss-app-config-dashboard">
                    <div>
                        <Form.Item name={["Id"]} noStyle>
                            <Input type="hidden" />
                        </Form.Item>
                        <Form.Item name={["Name"]} noStyle>
                            <Input type="hidden" />
                        </Form.Item>
                        <Form.Item name={["Enabled"]} noStyle>
                            <Input type="hidden" />
                        </Form.Item>
                        <Form.Item
                            label="Host URL"
                            name={["Url"]}
                            rules={[
                                {
                                    type: "url",
                                    message: "Invalid Link address.",
                                },
                            ]}>
                            <Input />
                        </Form.Item>

                        <Form.List name={["Forms"]}>
                            {(fields, { add, remove }) => {
                                return (
                                    <div className="ss-app-config-form-list">
                                        <h3>
                                            <span>Forms</span>
                                            <span>
                                                <Button
                                                    type="primary"
                                                    icon={<PlusOutlined />}
                                                    onClick={() => {
                                                        add(EMPTY_FORM);
                                                        setActiveTab(
                                                            (form.getFieldsValue().Forms.length - 1).toString()
                                                        );
                                                    }}>
                                                    <span className="m-l-8">New Form</span>
                                                </Button>
                                            </span>
                                        </h3>
                                        <Tabs tabPosition="left" activeKey={activeTab} onTabClick={setActiveTab}>
                                            {fields.map(({ name }, _Indx) => {
                                                const _Form = form.getFieldsValue().Forms[_Indx];

                                                return (
                                                    <Tabs.TabPane
                                                        key={_Indx}
                                                        tab={
                                                            <LinkTabLabel
                                                                Name={_Form.Name}
                                                                Icon={_Form.Icon}
                                                                Text={_Form.Text}
                                                            />
                                                        }>
                                                        <div className="ss-app-config-form-item">
                                                            <div className="ss-app-config-group-links">
                                                                <h4>Form</h4>
                                                                <div className="ss-app-config-group-toolbar">
                                                                    <FormDeleteButton
                                                                        label={_Form.IsNew ? "Cancel" : "Remove Form"}
                                                                        onClick={() => {
                                                                            let curValues = form.getFieldsValue();
                                                                            curValues.Forms = curValues.Forms.filter(
                                                                                (_: any, i: number) => i !== _Indx
                                                                            );
                                                                            form.setFieldsValue(curValues);
                                                                            setActiveTab(
                                                                                (curValues.Forms.length - 1).toString()
                                                                            );
                                                                        }}
                                                                    />
                                                                </div>
                                                            </div>

                                                            <MenuFormFields
                                                                showLink={false}
                                                                hasTplId={true}
                                                                name={[name]}
                                                            />
                                                        </div>
                                                    </Tabs.TabPane>
                                                );
                                            })}
                                        </Tabs>
                                    </div>
                                );
                            }}
                        </Form.List>
                    </div>
                </div>
            </Form>
        </Spin>
    );
};

export const FormDeleteButton: React.FC<{
    onClick: () => void;
    label: string;
}> = ({ label, onClick }) => (
    <Button
        danger
        size="small"
        icon={<AppIcon className="m-r-4" asset="delete" width="16" height="16" stroke="#ff4d4f" />}
        onClick={() => onClick()}>
        {label}
    </Button>
);
