import moment from "moment";

export type dateFormat = "short" | "medium" | "long" | "file";

export const APP_DATE_FORMAT = "DD/MM/YYYY";

export const genDateDisplay = (date: string, format: dateFormat = "short") => {
    switch (format) {
        case "short":
            return moment(date, APP_DATE_FORMAT).format("MMM YYYY");
        case "medium":
            return moment(date, APP_DATE_FORMAT).format("Do DD MMM YYYY");
        case "long":
            return moment(date, APP_DATE_FORMAT).format("Do DD MMM YYYY");
        case "file":
            return moment(date, APP_DATE_FORMAT).format("DD_MMM_YYYY");
    }
};

export const getFiveMosLater = (strDate: string) => {
    const _date = moment(strDate, APP_DATE_FORMAT);
    return _date.subtract(5, "month").format(APP_DATE_FORMAT);
};

export const getMonthsFromDateRange = (
    sDate: string,
    eDate: string
): number[] => {
    const start = moment(sDate, APP_DATE_FORMAT);
    const end = moment(eDate, APP_DATE_FORMAT);
    let months: number[] = [];
    while (end.isSameOrAfter(start)) {
        const mon = parseInt(start.format("M"));
        if (!months.includes(mon)) months.push(mon);
        start.add(1, "M");
    }
    return months;
};

export const getDateNumValue = (date: string) => {
    const mDate = moment(date, APP_DATE_FORMAT);
    const day = parseInt(mDate.format("D"));
    const month = parseInt(mDate.format("M"));
    const daysInMon = mDate.daysInMonth();

    return Math.round((month + day / daysInMon + Number.EPSILON) * 100) / 100;
};
