import React from "react";
import { Checkbox, Form, Input } from "antd";

import { IconSelect } from "../../IconSelect";

interface Props {
    name: (string | number)[];
    hideNameField?: boolean;
    showLink?: boolean;
    hasTplId?: boolean;
}

export const MenuFormFields: React.FC<Props> = ({ name, showLink, hasTplId, hideNameField = false }) => {
    return (
        <div className="ss-app-config-menu-form-fields">
            <Form.Item
                name={[...name, "Text"]}
                label="Link Text"
                rules={[
                    {
                        required: true,
                        message: "Please input Link text",
                    },
                ]}>
                <Input />
            </Form.Item>
            <Form.Item label="Link Name" name={[...name, "Name"]} noStyle={hideNameField}>
                <Input type={hideNameField ? "hidden" : "text"} />
            </Form.Item>

            <Form.Item name={[...name, "Enabled"]} label="Enabled" valuePropName="checked">
                <Checkbox />
            </Form.Item>
            {!hasTplId && (
                <Form.Item name={[...name, "External"]} label="External" valuePropName="checked">
                    <Checkbox />
                </Form.Item>
            )}
            <Form.Item
                name={[...name, "Icon"]}
                label="Link Icon"
                rules={[
                    {
                        required: true,
                        message: "Please select icon",
                    },
                ]}>
                <IconSelect />
            </Form.Item>
            {showLink && (
                <Form.Item
                    name={[...name, "Url"]}
                    label="Link URL"
                    rules={[
                        {
                            required: true,
                            message: "Please input a URL",
                        },
                        {
                            type: "url",
                            message: "Invalid Link address.",
                        },
                    ]}>
                    <Input />
                </Form.Item>
            )}
            {!hasTplId ? (
                <Form.Item
                    rules={[{ required: true, message: "Page ESS ID is required." }]}
                    name={[...name, "PageId"]}
                    label="ESS Page ID">
                    <Input />
                </Form.Item>
            ) : (
                <Form.Item name={[...name, "TemplateId"]} label="Template ID">
                    <Input />
                </Form.Item>
            )}
        </div>
    );
};
